/* @autogenerated */
import { Injectable } from '@angular/core';
import { NavigationEnd, Router } from '@angular/router';
import { combineLatest, filter, take } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';

export const AUTHORIZATION_ROUTES = ['/login-redirect', '/unauthorized'];

@Injectable({ providedIn: 'root' })
export class AuthorizationAccessService {
  // sessionStorage: la última ruta es de cada pestaña y sobrevive a la ida y vuelta al proveedor de identidad
  private readonly storageKey = 'last-non-oidc-route';

  constructor(
    private router: Router,
    private state: AppStateService,
  ) {
    this.router.events
      .pipe(filter((event): event is NavigationEnd => event instanceof NavigationEnd))
      .subscribe((event) => this.remember(event.urlAfterRedirects));
  }

  isAuthRoute(url: string): boolean {
    return AUTHORIZATION_ROUTES.some((route) => url.startsWith(route));
  }

  /** Guarda `url` como la ruta a la que volver tras iniciar sesión, salvo que sea una ruta de autorización. */
  remember(url: string): void {
    if (!this.isAuthRoute(url)) {
      sessionStorage.setItem(this.storageKey, url);
    }
  }

  getLastRoute(): string | null {
    return sessionStorage.getItem(this.storageKey);
  }

  loadLastRoute() {
    const last = this.getLastRoute();
    if (last) {
      this.router.navigateByUrl(last);
    } else {
      combineLatest([this.state.language$, this.state.tenant$])
        .pipe(take(1))
        .subscribe(([language, tenant]) => this.router.navigate([language, tenant]));
    }
  }

  clear(): void {
    sessionStorage.removeItem(this.storageKey);
  }
}
